import "./physics-comparison.css";
import { useState } from "react";

export function PhysicsComparisonDemo() {
  const [animate, setAnimate] = useState(false);

  return (
    <div className="demo">
      <button onClick={() => setAnimate(!animate)}>
        {animate ? "Reset" : "Animate"}
      </button>

      <div className="row">
        <span className="label">Linear</span>
        <div
          className={`box box--linear ${animate ? "box--moved" : ""}`}
        />
      </div>

      <div className="row">
        <span className="label">Ease-out</span>
        <div
          className={`box box--ease-out ${animate ? "box--moved" : ""}`}
        />
      </div>

      <div className="row">
        <span className="label">Spring</span>
        <div
          className={`box box--spring ${animate ? "box--moved" : ""}`}
        />
      </div>
    </div>
  );
}

.box {
  width: 48px;
  height: 48px;
  border-radius: 4px;
}

/_ Linear: constant speed, abrupt stop _/
.box--linear {
  background: #a3a3a3;
  transition: transform 500ms linear;
}

/_ Ease-out: decelerates into position _/
.box--ease-out {
  background: #737373;
  transition: transform 500ms cubic-bezier(0.16, 1, 0.3, 1);
}

/_ Spring-like: overshoot with settle _/
.box--spring {
  background: #525252;
  transition: transform 500ms
    cubic-bezier(0.34, 1.56, 0.64, 1);
}

.box--moved {
  transform: translateX(200px);
}
